function App() {
  const [useLayout, setUseLayout] = useState(true);
  const btnRef = useRef(null);
  const [left, setLeft] = useState(0);
  const effect = useLayout ? useLayoutEffect : useEffect;
  effect(() => {
    const r = btnRef.current.getBoundingClientRect();
    setLeft(r.left + r.width / 2 - 40);
  });
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <label><input type="checkbox" checked={useLayout} onChange={e => setUseLayout(e.target.checked)} /> use useLayoutEffect</label>
      <div style={{ position: 'relative', marginTop: 40 }}>
        <button ref={btnRef} style={{ marginLeft: 80 }}>Trigger</button>
        <div style={{ position: 'absolute', top: -28, left, width: 80, textAlign: 'center', background: '#111', color: '#fff', borderRadius: 4 }}>tip</div>
      </div>
    </div>
  );
}

